(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 390;
  const lanes = [91, 194, 297];
  const padXs = [140, 242, 344];
  const pads = [];
  lanes.forEach((y, row) => padXs.forEach((x, col) => pads.push({x, y, row, col, building:null})));
  const defs = [
    {id:'foundry',name:'Shard Foundry',desc:'Launches quick, balanced shardlings.',cost:65,icon:'⬟',color:'#69edc1',kind:'producer',rate:5.0,unit:'shard',key:'1',tag:'UNIT · RAPID'},
    {id:'prism',name:'Prism Lab',desc:'Deploys long-range prism archers.',cost:95,icon:'◇',color:'#75cfff',kind:'producer',rate:7.3,unit:'prism',key:'2',tag:'UNIT · RANGED'},
    {id:'bulwark',name:'Bulwark Forge',desc:'Slow armored guardians hold the lane.',cost:105,icon:'⬢',color:'#ffd276',kind:'producer',rate:9.5,unit:'tank',key:'3',tag:'UNIT · TANK'},
    {id:'hatchery',name:'Swarm Hatchery',desc:'Floods the front with tiny biters.',cost:120,icon:'✣',color:'#f38bce',kind:'producer',rate:8.0,unit:'drone',key:'4',tag:'UNIT · SWARM'},
    {id:'pulse',name:'Pulse Array',desc:'Chains electric bursts across enemies.',cost:115,icon:'✳',color:'#a9a0ff',kind:'tower',range:270,rate:1.75,damage:16,key:'5',tag:'TOWER · CHAIN'},
    {id:'longshot',name:'Longshot Nest',desc:'Piercing shots. Highest range & damage.',cost:145,icon:'△',color:'#ff9d79',kind:'tower',range:410,rate:2.55,damage:34,key:'6',tag:'TOWER · SNIPER'},
    {id:'coin',name:'Coin Engine',desc:'Refines alloy continuously. +1.8 alloy / sec.',cost:85,icon:'◈',color:'#8ff0b9',kind:'economy',income:1.8,key:'7',tag:'ECONOMY · +1.8/S'},
    {id:'beacon',name:'Repair Beacon',desc:'Restores core integrity every 14 seconds.',cost:130,icon:'✚',color:'#80d9ff',kind:'repair',rate:14,key:'8',tag:'SUPPORT · REPAIR'}
  ];
  const unitStats = {
    shard:{hp:48,speed:32,range:36,damage:12,rate:1.05,color:'#68f0c1',shape:'diamond',size:10},
    prism:{hp:36,speed:23,range:155,damage:15,rate:1.45,color:'#73cfff',shape:'triangle',size:10},
    tank:{hp:190,speed:13,range:40,damage:27,rate:1.55,color:'#ffd276',shape:'hex',size:15},
    drone:{hp:22,speed:44,range:25,damage:7,rate:.65,color:'#f38bce',shape:'circle',size:7}
  };
  const enemyTypes = [
    {name:'Bit',shape:'triangle',color:'#ff887d',hp:38,speed:16,damage:10,reward:7,size:9},
    {name:'Rammer',shape:'square',color:'#ffb06e',hp:95,speed:9,damage:19,reward:12,size:13},
    {name:'Wisp',shape:'diamond',color:'#d88bff',hp:45,speed:25,damage:8,reward:9,size:9},
    {name:'Brute',shape:'hex',color:'#ff6e91',hp:260,speed:6.7,damage:32,reward:23,size:17}
  ];
  let units=[], enemies=[], shots=[], particles=[], floating=[];
  let credits=110, core=100, kills=0, elapsed=0, wave=1, waveClock=0, spawnClock=0, spawnCount=0;
  let selected=null, paused=false, gameOver=false, gameSpeed=1, soundOn=false, lastFrame=0, toastTimer=0, audioCtx=null;
  let seeded=false;
  const $ = id => document.getElementById(id);
  const creditEl=$('creditValue'), waveEl=$('waveValue'), coreEl=$('coreValue');

  function resize(){const dpr=Math.min(window.devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.width*dpr*H/W));ctx.setTransform(canvas.width/W,0,0,canvas.width/W,0,0)}
  window.addEventListener('resize',resize); resize();
  function uiBuild(){const grid=$('buildGrid');grid.innerHTML='';defs.forEach((d,i)=>{const b=document.createElement('button');b.className='build-card';b.type='button';b.dataset.id=d.id;b.innerHTML=`<span class="card-icon" style="color:${d.color}">${d.icon}</span><span class="card-key">${d.key}</span><span class="card-title">${d.name}</span><span class="card-desc">${d.desc}</span><span class="card-bottom"><span class="card-cost">◈ ${d.cost}</span><span class="card-type">${d.tag}</span></span>`;b.addEventListener('click',()=>selectBuild(d));grid.appendChild(b)});updateHud()}
  function selectBuild(d){if(gameOver)return;if(credits<d.cost){notify('NOT ENOUGH ALLOY');return}selected=selected?.id===d.id?null:d;updateCards();$('hintText').textContent=selected?`PLACE ${selected.name.toUpperCase()} ON AN EMPTY PAD · ESC TO CANCEL`:'SELECT A STRUCTURE · THEN PLACE IT ON AN EMPTY PAD';if(selected)beep(540,.045)}
  function updateCards(){document.querySelectorAll('.build-card').forEach(b=>{const d=defs.find(x=>x.id===b.dataset.id);b.classList.toggle('selected',selected?.id===d.id);b.disabled=credits<d.cost&&!selected?.id===d.id;const c=b.querySelector('.card-cost');c.classList.toggle('short',credits<d.cost);c.classList.toggle('affordable',credits>=d.cost)})}
  function updateHud(){creditEl.textContent=Math.floor(credits);waveEl.textContent=String(wave).padStart(2,'0');$('sectorValue').textContent=String(Math.floor((wave-1)/5)+1).padStart(2,'0');coreEl.textContent=`${Math.max(0,Math.ceil(core))}%`;$('coreMeter').style.width=`${Math.max(0,core)}%`;$('killValue').textContent=kills;$('incomeValue').textContent=(.7+pads.reduce((n,p)=>n+(p.building?.def.kind==='economy'?p.building.def.income*(1+(p.building.level-1)*.5):0),0)).toFixed(1);$('timeValue').textContent=fmt(elapsed);$('waveProgress').style.width=`${Math.min(100,waveClock/35*100)}%`;$('buildCount').textContent=`${pads.filter(p=>p.building).length} / 9 PADS FILLED`;updateCards()}
  function fmt(t){const s=Math.floor(t);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
  function notify(s){const el=$('toast');el.textContent=s;el.classList.add('show');toastTimer=1.6}
  function beep(freq=450,dur=.05){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(_){}}
  function place(p){if(!selected||p.building||gameOver)return;if(credits<selected.cost){notify('NOT ENOUGH ALLOY');return}credits-=selected.cost;p.building={def:selected,level:1,timer:selected.rate||0, hp:100};floatText(p.x,p.y-25,'-'+selected.cost,'#ffd477');burst(p.x,p.y,selected.color,12);notify(`${selected.name.toUpperCase()} CONSTRUCTED`);beep(720,.08);selected=null;$('hintText').textContent='SELECT A STRUCTURE · THEN PLACE IT ON AN EMPTY PAD';updateHud()}
  function interact(p){if(!p.building){place(p);return}const b=p.building,price=Math.round(b.def.cost*(.55+b.level*.28));if(b.level<4&&credits>=price){credits-=price;b.level++;b.hp=100;burst(p.x,p.y,b.def.color,18);floatText(p.x,p.y-30,`LEVEL ${b.level}`,'#9bffe0');notify(`${b.def.name.toUpperCase()} UPGRADED`);beep(850,.09);updateHud()}else if(b.level>=4)notify('STRUCTURE AT MAX LEVEL');else notify(`UPGRADE COST: ${price} ALLOY`)}
  canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.width*W;let closest=null,dist=10000;for(const p of pads){const d=Math.hypot(p.x-x,p.y-y);if(d<dist){dist=d;closest=p}}if(dist<38)interact(closest)});
  canvas.addEventListener('contextmenu',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.width*W;const p=pads.find(q=>Math.hypot(q.x-x,q.y-y)<36);if(p?.building){const refund=Math.floor(p.building.def.cost*.48*p.building.level);credits+=refund;floatText(p.x,p.y-25,'+'+refund,'#a8ffd8');burst(p.x,p.y,p.building.def.color,12);p.building=null;notify('STRUCTURE RECYCLED');updateHud()}});
  $('cancelBtn').onclick=()=>{selected=null;updateCards();$('hintText').textContent='SELECT A STRUCTURE · THEN PLACE IT ON AN EMPTY PAD'};
  $('pauseBtn').onclick=togglePause;$('restartBtn').onclick=reset;$('soundBtn').onclick=()=>{soundOn=!soundOn;$('soundBtn').classList.toggle('active',soundOn);if(soundOn)beep(660,.08)};
  $('speedLabel').addEventListener('click',()=>{gameSpeed=gameSpeed===1?2:1;$('speedLabel').innerHTML=`SIMULATION <b>${gameSpeed}×</b>`;notify(gameSpeed===2?'SIMULATION SPEED ×2':'SIMULATION SPEED ×1')});
  function togglePause(){if(gameOver)return;paused=!paused;$('pauseOverlay').classList.toggle('show',paused);$('pauseBtn').classList.toggle('active',paused)}
  window.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();togglePause()}if(e.key==='Escape'){selected=null;updateCards();$('hintText').textContent='SELECT A STRUCTURE · THEN PLACE IT ON AN EMPTY PAD'}const n=Number(e.key);if(n>=1&&n<=8)selectBuild(defs[n-1])});
  function reset(){units=[];enemies=[];shots=[];particles=[];floating=[];credits=110;core=100;kills=0;elapsed=0;wave=1;waveClock=0;spawnClock=0;spawnCount=0;selected=null;paused=false;gameOver=false;gameSpeed=1;pads.forEach(p=>p.building=null);pads[3].building={def:defs[0],level:1,timer:1.6,hp:100};$('overlay').classList.remove('show');$('pauseOverlay').classList.remove('show');$('pauseBtn').classList.remove('active');$('speedLabel').innerHTML='SIMULATION <b>1×</b>';$('hintText').textContent='SELECT A STRUCTURE · THEN PLACE IT ON AN EMPTY PAD';updateHud();notify('STARTER FOUNDRY ONLINE · BUILD YOUR DEFENSE');}
  function spawnUnit(p,def){const st=unitStats[def.unit];const scale=1+(wave-1)*.028+(p.building.level-1)*.16;units.push({x:p.x+24,y:p.y+(Math.random()*8-4),lane:p.row,kind:def.unit,hp:st.hp*scale,maxHp:st.hp*scale,speed:st.speed*(1+(p.building.level-1)*.06),range:st.range*(1+(p.building.level-1)*.1),damage:st.damage*(1+(p.building.level-1)*.18),rate:st.rate,cd:Math.random()*.4,color:st.color,shape:st.shape,size:st.size,phase:Math.random()*6.28});burst(p.x+18,p.y,st.color,4)}
  function spawnEnemy(){const difficulty=1+(wave-1)*.2;let pick;if(wave<3)pick=Math.random()<.78?0:1;else if(wave<6)pick=Math.random()<.52?0:Math.random()<.65?1:2;else{const r=Math.random();pick=r<.34?0:r<.57?1:r<.82?2:3}const t=enemyTypes[pick],lane=Math.floor(Math.random()*3),elite=(wave>4&&Math.random()<Math.min(.22,(wave-3)*.022));const mult=difficulty*(elite?1.55:1);enemies.push({x:W+24,y:lanes[lane]+(Math.random()*16-8),lane,type:pick,hp:t.hp*mult,maxHp:t.hp*mult,speed:t.speed*(1+Math.min(.4,(wave-1)*.018))*(elite?1.12:1),damage:t.damage*(1+(wave-1)*.11),reward:Math.floor(t.reward*(1+(wave-1)*.09)),range:t.size+22,rate:1.45,cd:0,shape:t.shape,color:elite?'#ff526f':t.color,size:t.size*(elite?1.2:1),elite,phase:Math.random()*6.28})}
  function shoot(from,to,damage,color,opts={}){shots.push({x:from.x,y:from.y-2,tx:to.x,ty:to.y,vx:opts.speed||360,damage,color,from, target:to,kind:opts.kind||'bolt',life:2,chain:opts.chain||0});}
  function closestEnemy(x,lane,range,forwardOnly=true){let best=null,bd=range;for(const e of enemies){if(e.lane!==lane)continue;const dx=e.x-x;if(forwardOnly&&dx< -8)continue;const d=Math.abs(dx);if(d<bd){bd=d;best=e}}return best}
  function update(dt){if(paused||gameOver)return;dt*=gameSpeed;elapsed+=dt;waveClock+=dt;spawnClock+=dt;credits+=.7*dt;for(const p of pads){const b=p.building;if(!b)continue;const d=b.def;if(d.kind==='producer'){b.timer-=dt;if(b.timer<=0){spawnUnit(p,d);b.timer+=d.rate*Math.pow(.91,b.level-1)}}else if(d.kind==='economy'){}else if(d.kind==='repair'){b.timer-=dt;if(b.timer<=0){const healed=Math.min(9+(b.level-1)*4,100-core);if(healed>0){core+=healed;floatText(p.x,p.y-24,'+'+Math.ceil(healed),'#84ddff');burst(p.x,p.y,d.color,10)}b.timer+=d.rate*Math.pow(.9,b.level-1)}}else if(d.kind==='tower'){b.timer-=dt;if(b.timer<=0){const range=d.range*(1+(b.level-1)*.16),target=enemies.filter(e=>e.lane===p.row&&e.x>p.x&&e.x-p.x<range).sort((a,b)=>a.x-b.x)[0];if(target){shoot({x:p.x+14,y:p.y-8},target,d.damage*(1+(b.level-1)*.32),d.color,{kind:d.id==='pulse'?'pulse':'sniper',chain:d.id==='pulse'?2:0,speed:d.id==='pulse'?450:580});b.timer=d.rate*Math.pow(.83,b.level-1)}else b.timer=.12}}}
    if(spawnClock>Math.max(.78,2.55-(wave-1)*.075)){spawnClock=0;spawnCount++;spawnEnemy()}
    if(waveClock>=35){waveClock-=35;wave++;spawnCount=0;notify(`WAVE ${String(wave).padStart(2,'0')} · SWARM EVOLVED`);burst(505,36,'#a09aff',18);beep(330,.18)}
    units.forEach(u=>{u.cd-=dt;const target=closestEnemy(u.x,u.lane,u.range,true);if(target){if(u.cd<=0){shoot(u,target,u.damage,u.color,{kind:'unit',speed:u.kind==='prism'?500:390});u.cd=u.rate}}else u.x+=u.speed*dt;u.phase+=dt*3});
    enemies.forEach(e=>{e.cd-=dt;const target=units.filter(u=>u.lane===e.lane&&Math.abs(u.x-e.x)<e.range+u.size).sort((a,b)=>Math.abs(a.x-e.x)-Math.abs(b.x-e.x))[0];if(target){if(e.cd<=0){target.hp-=e.damage;floatText(target.x,target.y-13,'-'+Math.ceil(e.damage),e.color);burst(target.x,target.y,e.color,3);e.cd=e.rate}}else e.x-=e.speed*dt;e.phase+=dt*2.7;if(e.x<68){core-=e.damage*.62;floatText(61,lanes[e.lane]-18,'-'+Math.ceil(e.damage*.62),'#ff897b');burst(65,lanes[e.lane],'#ff806e',12);e.hp=0;beep(155,.11)}});
    for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.life-=dt;if(!s.target||s.target.hp<=0){shots.splice(i,1);continue}const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy),step=s.vx*dt;if(d<step+8){hit(s.target,s.damage,s.color);if(s.kind==='pulse'&&s.chain>0){const next=enemies.filter(e=>e!==s.target&&e.lane===s.target.lane&&Math.abs(e.x-s.target.x)<85).sort((a,b)=>Math.abs(a.x-s.target.x)-Math.abs(b.x-s.target.x))[0];if(next){hit(next,s.damage*.65,s.color);if(s.chain>1){const next2=enemies.find(e=>e!==next&&e!==s.target&&e.lane===next.lane&&Math.abs(e.x-next.x)<85);if(next2)hit(next2,s.damage*.42,s.color)}}}shots.splice(i,1)}else{s.x+=dx/d*step;s.y+=dy/d*step}}
    for(let i=enemies.length-1;i>=0;i--){if(enemies[i].hp<=0){const e=enemies[i];if(e.hp<0||e.x<68){if(e.x>=68){kills++;credits+=e.reward;floatText(e.x,e.y-16,'+'+e.reward,'#a8ffd8');burst(e.x,e.y,e.color,e.elite?14:8)}}enemies.splice(i,1)}}
    units=units.filter(u=>u.hp>0&&u.x<W+40);updateEffects(dt);if(core<=0){core=0;endGame()}if(Math.floor(elapsed)%2===0)updateHud();
  }
  function hit(e,damage,color){if(!e||e.hp<=0)return;e.hp-=damage;burst(e.x,e.y,color,3);if(e.hp<=0){kills++;credits+=e.reward;floatText(e.x,e.y-18,'+'+e.reward,'#a8ffd8');burst(e.x,e.y,e.color,e.elite?17:10);beep(230,.045)}}
  function endGame(){gameOver=true;$('finalWave').textContent=String(wave).padStart(2,'0');$('finalKills').textContent=kills;$('finalTime').textContent=fmt(elapsed);$('overlay').classList.add('show');beep(95,.45)}
  function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=20+Math.random()*90;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.25+Math.random()*.5,max:.75,color,size:1+Math.random()*2.5})}}
  function floatText(x,y,text,color){floating.push({x,y,text,color,life:.9})}
  function updateEffects(dt){particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97});particles=particles.filter(p=>p.life>0);floating.forEach(f=>{f.life-=dt;f.y-=20*dt});floating=floating.filter(f=>f.life>0);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}}

  let pointer={x:-100,y:-100},hoverPad=null,hudClock=0;
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*W;pointer.y=(e.clientY-r.top)/r.width*W;hoverPad=pads.find(p=>Math.hypot(p.x-pointer.x,p.y-pointer.y)<38)||null});
  canvas.addEventListener('pointerleave',()=>{hoverPad=null});
  function polygon(x,y,r,n,rot=-Math.PI/2){ctx.beginPath();for(let i=0;i<n;i++){const a=rot+i*Math.PI*2/n;const px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath()}
  function shape(x,y,r,type,color,angle=0){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.shadowColor=color;ctx.shadowBlur=12;if(type==='circle'){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill()}else if(type==='square'){ctx.fillRect(-r*.76,-r*.76,r*1.52,r*1.52)}else{polygon(0,0,r,type==='hex'?6:type==='diamond'?4:3,type==='diamond'?Math.PI/4:-Math.PI/2);ctx.fill()}ctx.shadowBlur=0;ctx.fillStyle='#0c1521';ctx.beginPath();ctx.arc(0,0,Math.max(1.7,r*.24),0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawBackground(){ctx.fillStyle='#0b1220';ctx.fillRect(0,0,W,H);const g=ctx.createRadialGradient(530,170,10,530,180,620);g.addColorStop(0,'#142234');g.addColorStop(.58,'#101a2a');g.addColorStop(1,'#0b111d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // Subtle forge grid and drifting stars
    ctx.strokeStyle='#91b6d012';ctx.lineWidth=1;for(let x=14;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=10;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
    for(let i=0;i<42;i++){const x=((i*197+elapsed*(i%3+1)*3)%(W-30))+15,y=(i*83%H);ctx.fillStyle=i%4===0?'#84ffd229':'#b0c9df14';ctx.fillRect(x,y,1.5,1.5)}
    // Defensive front / lanes
    lanes.forEach((y,i)=>{ctx.fillStyle='#17243755';ctx.fillRect(16,y-37,968,74);ctx.fillStyle='#23324955';ctx.fillRect(16,y-38,968,1);ctx.fillRect(16,y+38,968,1);ctx.setLineDash([3,8]);ctx.strokeStyle='#7289a51b';ctx.beginPath();ctx.moveTo(402,y);ctx.lineTo(970,y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#8194aa58';ctx.font='9px "DM Mono"';ctx.fillText('LANE 0'+(i+1),414,y-25)});
    // Enemy breach field
    const pulse=.5+Math.sin(elapsed*3)*.5;const rg=ctx.createLinearGradient(900,0,1000,0);rg.addColorStop(0,'#ff746f00');rg.addColorStop(1,`rgba(255,87,102,${.04+pulse*.04})`);ctx.fillStyle=rg;ctx.fillRect(900,0,100,H);ctx.strokeStyle='#ff777a77';ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(956,12);ctx.lineTo(956,H-12);ctx.stroke();ctx.setLineDash([]);
    // Core / friendly gate
    ctx.save();ctx.shadowColor='#69eac2';ctx.shadowBlur=18;ctx.fillStyle='#1a504c';polygon(52,194,29,6,Math.PI/6);ctx.fill();ctx.strokeStyle='#6bf0c4';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();shape(52,194,13,'diamond','#70f4ce',elapsed*.4);ctx.fillStyle='#91d9c5';ctx.font='8px "DM Mono"';ctx.textAlign='center';ctx.fillText('CORE',52,236);ctx.textAlign='left';
    ctx.fillStyle='#ff8b7b';ctx.font='8px "DM Mono"';ctx.fillText('BREACH',950,12);
  }
  function drawPad(p){const b=p.building,isHover=hoverPad===p,active=selected&&!b;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=b?'#131f2c':'#152032';ctx.strokeStyle=b?`${b.def.color}70`:isHover?'#75edc9':active?'#60d9b688':'#46546a';ctx.lineWidth=isHover||active?1.5:1;ctx.beginPath();ctx.roundRect(-31,-28,62,56,9);ctx.fill();ctx.stroke();ctx.setLineDash([3,4]);ctx.strokeStyle=b?`${b.def.color}38`:'#8fa5bc32';ctx.beginPath();ctx.roundRect(-25,-22,50,44,6);ctx.stroke();ctx.setLineDash([]);
    if(!b){ctx.fillStyle=active?'#82f1ca': '#718097';ctx.globalAlpha=active?.75:.45;ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText('+',0,7);ctx.globalAlpha=1;if(active){ctx.shadowColor='#64edc3';ctx.shadowBlur=12;ctx.strokeStyle='#69edc1';ctx.globalAlpha=.35+Math.sin(elapsed*4)*.2;ctx.beginPath();ctx.arc(0,0,37,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.shadowBlur=0}}else drawBuilding(p);ctx.restore()}
